import atexit
import random
import sys
import threading
import time
import uuid
import warnings
from dataclasses import asdict
from queue import Empty, Full, Queue

import requests

from mlflow.environment_variables import _MLFLOW_TELEMETRY_SESSION_ID
from mlflow.telemetry.constant import (
    BATCH_SIZE,
    BATCH_TIME_INTERVAL_SECONDS,
    MAX_QUEUE_SIZE,
    MAX_WORKERS,
    RETRYABLE_ERRORS,
    UNRECOVERABLE_ERRORS,
)
from mlflow.telemetry.schemas import (
    Record,
    TelemetryConfig,
    TelemetryInfo,
    get_source_sdk,
)
from mlflow.telemetry.utils import _get_config_url, _log_error, is_telemetry_disabled
from mlflow.utils.logging_utils import should_suppress_logs_in_thread
from mlflow.version import VERSION


class TelemetryClient:
    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self._clean_up()

    def __init__(self):
        session_id = _MLFLOW_TELEMETRY_SESSION_ID.get() or uuid.uuid4().hex
        self.info = asdict(TelemetryInfo(session_id=session_id))
        self.config: TelemetryConfig | None = None

        self._batch_size = BATCH_SIZE
        self._batch_time_interval = BATCH_TIME_INTERVAL_SECONDS
        self._max_workers = MAX_WORKERS
        self._queue: Queue[list[Record]] = Queue(maxsize=MAX_QUEUE_SIZE)
        self._pending_records: list[Record] = []
        self._last_batch_time = time.time()

        self._lock = threading.Lock()
        self._batch_lock = threading.Lock()
        self._consumer_threads: list[threading.Thread] = []
        self._config_thread: threading.Thread | None = None
        self._atexit_registered = False
        self._is_active = False
        self._is_stopped = False
        self._is_config_fetched = False

    def _at_exit_callback(self) -> None:
        previous_suppression = should_suppress_logs_in_thread.get()
        error = None
        try:
            should_suppress_logs_in_thread.set(True)
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                self.flush(terminate=True)
        except Exception as e:
            error = e
        finally:
            should_suppress_logs_in_thread.set(previous_suppression)

        if error is not None:
            _log_error(f"Failed to terminate telemetry client: {error}")

    def _get_config(self):
        try:
            config_url = _get_config_url(VERSION)
            if config_url is None:
                return

            try:
                response = requests.get(config_url, timeout=1)
            except (
                requests.exceptions.RequestException,
                ConnectionError,
                TimeoutError,
            ):
                return

            if response.status_code != 200:
                return

            config = response.json()
            if config.get("mlflow_version") != VERSION:
                return
            if config.get("disable_telemetry", True):
                return

            ingestion_url = config.get("ingestion_url")
            if not ingestion_url:
                return
            if get_source_sdk().value in config.get("disable_sdks", []):
                return

            disabled_os = config.get("disable_os", config.get("disabled_os", []))
            if sys.platform in disabled_os:
                return

            rollout_percentage = config.get("rollout_percentage", 0)
            if random.random() * 100 >= rollout_percentage:
                return

            self.config = TelemetryConfig(
                ingestion_url=ingestion_url,
                disable_events=set(config.get("disable_events", [])),
            )
        except Exception as e:
            _log_error(f"Failed to fetch telemetry configuration: {e}")
        finally:
            self._is_config_fetched = True
            if self.config is None:
                self._is_stopped = True
                self.is_active = False
                _set_telemetry_client(None)

    def activate(self) -> None:
        with self._lock:
            if self.is_active or self._is_stopped:
                return

            self.is_active = True
            self._config_thread = threading.Thread(
                target=self._get_config,
                name="MlflowTelemetryConfig",
                daemon=True,
            )
            self._config_thread.start()

            for worker_index in range(self._max_workers):
                thread = threading.Thread(
                    target=self._consumer,
                    name=f"MlflowTelemetryConsumer-{worker_index}",
                    daemon=True,
                )
                self._consumer_threads.append(thread)
                thread.start()

            if not self._atexit_registered:
                atexit.register(self._at_exit_callback)
                self._atexit_registered = True

    def add_record(self, record: Record):
        if self._is_stopped:
            return
        if not self.is_active:
            self.activate()
        if self._is_stopped:
            return

        with self._batch_lock:
            if self._is_stopped:
                return
            self._pending_records.append(record)
            if len(self._pending_records) >= self._batch_size:
                self._send_batch()

    def _send_batch(self) -> bool:
        if not self._pending_records:
            return True

        batch = self._pending_records[: self._batch_size]
        try:
            self._queue.put_nowait(batch)
        except Full:
            _log_error(
                "Telemetry queue is full; the pending batch will be retried later"
            )
            return False

        del self._pending_records[: len(batch)]
        self._last_batch_time = time.time()
        return True

    def _process_records(self, records: list[Record], request_timeout: float = 1):
        """Process a batch of telemetry records."""
        try:
            self._update_backend_store()
            if self.info["tracking_uri_scheme"] in [
                "databricks",
                "databricks-uc",
                "uc",
            ]:
                self._is_stopped = True
                # set config to None to allow consumer thread drop records in the queue
                self.config = None
                self.is_active = False
                _set_telemetry_client(None)
                return

            config = self.config
            if config is None:
                return

            records = [
                {
                    "data": self.info | record.to_dict(),
                    # use random uuid as partition key to make sure records are
                    # distributed evenly across shards
                    "partition-key": uuid.uuid4().hex,
                }
                for record in records
            ]
            # changing this value can affect total time for processing records
            # the total time = request_timeout * max_attempts + sleep_time * (max_attempts - 1)
            max_attempts = 3
            sleep_time = 1
            for i in range(max_attempts):
                should_retry = False
                response = None
                try:
                    response = requests.post(
                        config.ingestion_url,
                        json={"records": records},
                        headers={"Content-Type": "application/json"},
                        timeout=request_timeout,
                    )
                    should_retry = response.status_code in RETRYABLE_ERRORS
                except (
                    requests.exceptions.ConnectionError,
                    requests.exceptions.Timeout,
                    ConnectionError,
                    TimeoutError,
                ):
                    should_retry = True
                # NB: DO NOT retry when terminating
                # otherwise this increases shutdown overhead significantly
                if self._is_stopped:
                    return
                if i < max_attempts - 1 and should_retry:
                    # we do not use exponential backoff to avoid increasing
                    # the processing time significantly
                    time.sleep(sleep_time)
                elif (
                    response is not None
                    and response.status_code in UNRECOVERABLE_ERRORS
                ):
                    self._is_stopped = True
                    self.is_active = False
                    # this is executed in the consumer thread, so
                    # we cannot join the thread here, but this should
                    # be enough to stop the telemetry collection
                    return
                else:
                    return
        except Exception as e:
            _log_error(f"Failed to send telemetry records: {e}")

    def _consumer(self) -> None:
        """Individual consumer that processes records from the queue."""
        # suppress logs in the consumer thread to avoid emitting any irrelevant
        # logs during telemetry collection.
        should_suppress_logs_in_thread.set(True)

        while not self._is_config_fetched and not self._is_stopped:
            time.sleep(0.1)

        while self.config and not self._is_stopped:
            try:
                records = self._queue.get(timeout=1)
            except Empty:
                # check if batch time interval has passed and send data if needed
                if time.time() - self._last_batch_time >= self._batch_time_interval:
                    self._last_batch_time = time.time()
                    with self._batch_lock:
                        if self._pending_records:
                            self._send_batch()
                continue

            try:
                self._process_records(records)
            finally:
                self._queue.task_done()

        # Drop queued records when configuration disables telemetry, transmission
        # stops, or the process is terminating. This also releases queue.join().
        while True:
            try:
                self._queue.get_nowait()
                self._queue.task_done()
            except Empty:
                break

    def flush(self, terminate=False) -> None:
        if not self.is_active:
            return

        if terminate:
            self._is_stopped = True
            self.is_active = False
            return

        config_thread = self._config_thread
        if config_thread is not None:
            config_thread.join(timeout=1)
        if not self._is_config_fetched:
            return

        if self.config is not None and not self._is_stopped:
            while not self._is_stopped:
                with self._batch_lock:
                    if not self._pending_records:
                        break
                    accepted = self._send_batch()
                if not accepted:
                    try:
                        self._queue.join()
                    except Exception as e:
                        _log_error(f"Failed to flush telemetry records: {e}")
                        return

        try:
            self._queue.join()
        except Exception as e:
            _log_error(f"Failed to flush telemetry records: {e}")

    def _clean_up(self) -> None:
        self.flush(terminate=True)
        current_thread = threading.current_thread()
        for thread in self._consumer_threads:
            if thread is not current_thread and thread.is_alive():
                thread.join(timeout=1)

    @property
    def is_active(self) -> bool:
        return self._is_active

    @is_active.setter
    def is_active(self, value: bool) -> None:
        self._is_active = value

    def _update_backend_store(self):
        """
        Backend store might be changed after mlflow is imported, we should use this
        method to update the backend store info at sending telemetry step.
        """
        try:
            # import here to avoid circular import
            from mlflow.tracking._tracking_service.utils import _get_tracking_scheme

            self.info["tracking_uri_scheme"] = _get_tracking_scheme()
        except Exception as e:
            _log_error(f"Failed to update backend store: {e}")


_MLFLOW_TELEMETRY_CLIENT = None
_client_lock = threading.Lock()


def set_telemetry_client():
    if is_telemetry_disabled():
        # set to None again so this function can be used to
        # re-initialize the telemetry client
        _set_telemetry_client(None)
    else:
        try:
            _set_telemetry_client(TelemetryClient())
        except Exception as e:
            _log_error(f"Failed to set telemetry client: {e}")
            _set_telemetry_client(None)


def _set_telemetry_client(value: TelemetryClient | None):
    global _MLFLOW_TELEMETRY_CLIENT
    with _client_lock:
        _MLFLOW_TELEMETRY_CLIENT = value
        if value:
            _MLFLOW_TELEMETRY_SESSION_ID.set(value.info["session_id"])
        else:
            _MLFLOW_TELEMETRY_SESSION_ID.unset()


def get_telemetry_client() -> TelemetryClient | None:
    with _client_lock:
        return _MLFLOW_TELEMETRY_CLIENT
import functools
import inspect
import logging
import time
from typing import Any, Callable, ParamSpec, TypeVar

from mlflow.environment_variables import MLFLOW_EXPERIMENT_ID
from mlflow.telemetry.client import get_telemetry_client
from mlflow.telemetry.events import Event
from mlflow.telemetry.schemas import Record, Status
from mlflow.telemetry.utils import _log_error, is_telemetry_disabled

P = ParamSpec("P")
R = TypeVar("R")

_logger = logging.getLogger(__name__)


def _is_telemetry_disabled_for_event(event: type[Event]) -> bool:
    """Return whether telemetry collection is disabled for an event type."""
    try:
        client = get_telemetry_client()
        if client is None:
            return True
        if not client._is_config_fetched:
            return False
        if client.config is None:
            return True
        return event.name in client.config.disable_events
    except Exception as e:
        _logger.error(
            "Failed to check telemetry status for event %s: %s",
            event.name,
            e,
            exc_info=True,
        )
        return True


def record_usage_event(
    event: type[Event],
) -> Callable[[Callable[P, R]], Callable[P, R]]:
    def decorator(func: Callable[P, R]) -> Callable[P, R]:
        @functools.wraps(func)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            if is_telemetry_disabled() or _is_telemetry_disabled_for_event(event):
                return func(*args, **kwargs)

            success = True
            result = None
            start_time = time.time()
            try:
                result = func(*args, **kwargs)
                return result  # noqa: RET504
            except Exception:
                success = False
                raise
            finally:
                try:
                    duration_ms = int((time.time() - start_time) * 1000)
                    _add_telemetry_record(
                        func, args, kwargs, success, duration_ms, event, result
                    )
                except Exception as e:
                    _log_error(f"Failed to record telemetry event {event.name}: {e}")

        return wrapper

    return decorator


def _add_telemetry_record(
    func: Callable[..., Any],
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
    success: bool,
    duration_ms: int,
    event: type[Event],
    result: Any,
) -> None:
    try:
        if client := get_telemetry_client():
            signature = inspect.signature(func)
            bound_args = signature.bind(*args, **kwargs)
            bound_args.apply_defaults()

            arguments = dict(bound_args.arguments)
            arguments.pop("self", None)

            params = list(arguments.keys())
            if params and params[0] == "cls" and isinstance(arguments["cls"], type):
                del arguments["cls"]

            record_params = event.parse(arguments) or {}
            if hasattr(event, "parse_result"):
                record_params.update(event.parse_result(result))
            if experiment_id := MLFLOW_EXPERIMENT_ID.get():
                record_params["mlflow_experiment_id"] = experiment_id
            record = Record(
                event_name=event.name,
                timestamp_ns=time.time_ns(),
                params=record_params or None,
                status=Status.SUCCESS if success else Status.FAILURE,
                duration_ms=duration_ms,
            )
            client.add_record(record)
    except Exception as e:
        _log_error(f"Failed to generate telemetry record for event {event.name}: {e}")


def _record_event(event: type[Event], params: dict[str, Any] | None = None) -> None:
    try:
        if is_telemetry_disabled() or _is_telemetry_disabled_for_event(event):
            return
        if client := get_telemetry_client():
            record_params = dict(params or {})
            if experiment_id := MLFLOW_EXPERIMENT_ID.get():
                record_params["mlflow_experiment_id"] = experiment_id
            client.add_record(
                Record(
                    event_name=event.name,
                    params=record_params or None,
                    timestamp_ns=time.time_ns(),
                    status=Status.SUCCESS,
                    duration_ms=0,
                )
            )
    except Exception as e:
        _log_error(f"Failed to record telemetry event {event.name}: {e}")
    return False


