def _get_config_url(version: str) -> str | None:
    """Return the telemetry configuration URL for an MLflow version."""
    parsed_version = Version(version)
    if parsed_version.local is not None:
        return None

    base_url = CONFIG_STAGING_URL if parsed_version.is_devrelease else CONFIG_URL
    return f"{base_url}/{version}.json"


